CREATE TABLE google_drive_connections (id VARCHAR(36) PRIMARY KEY, owner_user_id VARCHAR(36) NOT NULL, account_email VARCHAR(254) NOT NULL, account_id VARCHAR(128) NOT NULL, credentials_ref TEXT NOT NULL, scopes TEXT, status VARCHAR(16) NOT NULL DEFAULT 'CONNECTED', last_refresh_at VARCHAR(40), last_error TEXT, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, INDEX idx_gdrive_connections_owner(owner_user_id), FOREIGN KEY(owner_user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE google_drive_source_connections (source_id VARCHAR(36) PRIMARY KEY, connection_id VARCHAR(36) NOT NULL, FOREIGN KEY(source_id) REFERENCES remote_sources(id) ON DELETE CASCADE, FOREIGN KEY(connection_id) REFERENCES google_drive_connections(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE google_drive_folders (id VARCHAR(36) PRIMARY KEY, source_id VARCHAR(36) NOT NULL, folder_id VARCHAR(128) NOT NULL, display_name VARCHAR(512) NOT NULL, created_at VARCHAR(40) NOT NULL, UNIQUE KEY uq_gdrive_folder(source_id, folder_id), FOREIGN KEY(source_id) REFERENCES remote_sources(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE google_drive_files (id VARCHAR(36) PRIMARY KEY, source_id VARCHAR(36) NOT NULL, file_id VARCHAR(128) NOT NULL, name VARCHAR(512) NOT NULL, size BIGINT, mime_type VARCHAR(128), modified_time VARCHAR(40), parents TEXT, media_file_id VARCHAR(36), last_seen_at VARCHAR(40) NOT NULL, missing_since VARCHAR(40), created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, UNIQUE KEY uq_gdrive_file(source_id, file_id), INDEX idx_gdrive_files_source(source_id, file_id), FOREIGN KEY(source_id) REFERENCES remote_sources(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE INDEX idx_gdrive_folders_source ON google_drive_folders(source_id);
